/**
 * Drops every document for one organization. A rebuild starts here so rows
 * that no longer have a live source cannot survive, and other organizations
 * are left untouched.
 */
export async function deleteSearchDocumentsForOrg(orgId: OrgId): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(orgPredicate(searchIndex.orgId, orgId))
    .run();
}

