/**
 * Searchable only while the issue and its project are both live. Otherwise the
 * issue and every comment on it are removed, including comments posted or
 * edited after the project was archived.
 */
export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  if (!(await issueIsSearchable(orgId, issue))) {
    await removeFromIndex(orgId, "issue", issue.id);
    await forEachComment(orgId, issue.id, async (comment) => {
      await removeFromIndex(orgId, "comment", comment.id);
    });
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\n"),
    issue.projectId,
  );
}

/**
 * Searchable only while the comment, its issue and that issue's project are
 * all live. A deleted comment or a comment under an archived ancestor is removed.
 */
export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  const projectId = await commentProjectIfSearchable(orgId, comment);
  if (projectId === null) {
    await removeFromIndex(orgId, "comment", comment.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    projectId,
  );
}

/** Searchable only while the project itself is live. */
export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  if (!isLive(project)) {
    await removeFromIndex(orgId, "project", project.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

