/**
 * Walks one tenant's projects, issues and comments and re-upserts every
 * document. Scoped to a single org on purpose: a full-fleet reindex is a
 * sequence of these, so one slow tenant cannot stall the rest.
 *
 * The org's index is cleared first, then every page of content — including
 * archived rows and rows older than the first page — is handed to the index
 * writers. They decide what is searchable, so a rebuild ends with exactly the
 * live documents for this workspace and does not touch any other workspace.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    await searchRepo.deleteSearchDocumentsForOrg(orgId);

    await forEachPage((cursor) =>
      projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor,
        includeArchived: true,
      }),
      async (project) => {
        try {
          await indexProject(orgId, project);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      },
    );

    await forEachPage((cursor) =>
      issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor,
        includeArchived: true,
      }),
      async (issue) => {
        try {
          await indexIssue(orgId, issue);
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }

        await forEachPage((commentCursor) =>
          commentRepo.listComments({
            orgId,
            issueId: issue.id,
            includeArchived: true,
            limit: PAGE_SIZE,
