 * do their comments.
 */
async function syncProjectSearch(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project) await indexProject(orgId, project);
  else await removeFromIndex(orgId, "project", projectId);

  await forEachIssue(orgId, projectId, async (issue) => {
    await indexIssue(orgId, issue);
    await forEachComment(orgId, issue.id, async (comment) => {
      await indexComment(orgId, comment);
    });
  });
}

async function issueIsSearchable(orgId: OrgId, issue: Issue): Promise<boolean> {
  if (!isLive(issue)) return false;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  return project !== null && isLive(project);
}

/** `null` when the comment must not be indexed. */
async function commentProjectIfSearchable(
  orgId: OrgId,
  comment: Comment,
): Promise<ProjectId | null> {
  if (!isLive(comment)) return null;
  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  if (!issue || !isLive(issue)) return null;
  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project || !isLive(project)) return null;
  return project.id;
}

async function forEachIssue(
  orgId: OrgId,
  projectId: ProjectId,
  visit: (issue: Issue) => Promise<void>,
): Promise<void> {
  await forEachPage(
    (cursor) =>
      issueRepo.listIssues({
        orgId,
        projectId,
        includeArchived: true,
        limit: SYNC_PAGE_SIZE,
        cursor,
      }),
    visit,
  );
}

async function forEachComment(
  orgId: OrgId,
  issueId: IssueId,
  visit: (comment: Comment) => Promise<void>,
): Promise<void> {
  await forEachPage(
    (cursor) =>
      commentRepo.listComments({
        orgId,
        issueId,
        includeArchived: true,
        limit: SYNC_PAGE_SIZE,
        cursor,
      }),
    visit,
  );
}

async function forEachPage<T>(
  load: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  const seen = new Set<string>();

  for (;;) {
    const page = await load(cursor);
    for (const item of page.items) {
      await visit(item);
    }
    const next = page.nextCursor;
    if (!next || page.items.length === 0 || seen.has(next)) return;
    seen.add(next);
    cursor = next;
  }
}

